```go
// allocationBefore 返回更正发生前该收款生效的分配。
func allocationBefore(s *state, c *correction) []paymentAllocation {
    p := s.Payments[c.PaymentID]
    before := p.Allocations
    var best *correction
    for _, o := range s.Corrections {
        if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (best == nil || o.Seq > best.Seq) {
            best = o
        }
    }
    if best != nil { before = best.Allocations }
    return before
}
```

