	h.runExpectErr("bill", "correct", "r1", "c1", "理由",
		"2026-09:9223372036854775806", "2026-10:2")
	// 月份无账单（未结算）。
	h.runExpectErr("bill", "correct", "r1", "c1", "理由", "2026-11:700")

